// refactor obligation to better handle operations
module protocol::obligation;

use protocol::ctoken::CToken;
use protocol::ctoken_table::{Self, CTokenTable};
use protocol::debt::{Self, Debt};
use protocol::error;
use std::type_name::{Self, TypeName};
use sui::balance::Balance;
use protocol::wit_table::{Self, WitTable};
use math::float::Decimal;

public struct ObligationOwnerCap has key, store {
    id: UID,
    obligation_id: ID,

    // redundant fields, but makes query slightly easier
    market_type: TypeName,
    market_id: ID,
}

public struct Obligation<phantom MarketType> has key, store {
    id: UID,
    // with market id, no need to track version
    lending_market_id: ID,
    debts: WitTable<ObligationDebts, TypeName, Debt>,
    ctokens: CTokenTable,

    emode_group: u8,
}

public fun id(self: &ObligationOwnerCap): ID {
    self.obligation_id
}

public(package) fun emode_group<MarketType>(self: &Obligation<MarketType>): u8 {
    self.emode_group
}

public(package) fun debts<MarketType>(
    self: &Obligation<MarketType>,
): &WitTable<ObligationDebts, TypeName, Debt> {
    &self.debts
}

public(package) fun market_id<MarketType>(self: &Obligation<MarketType>): ID {
    self.lending_market_id
}

public(package) fun new<MarketType>(
    lending_market_id: ID,
    emode_group: u8,
    ctx: &mut TxContext,
): (Obligation<MarketType>, ObligationOwnerCap) {
    let obligation = Obligation {
        id: object::new(ctx),
        lending_market_id,
        debts: wit_table::new(ObligationDebts {}, true, ctx),
        ctokens: ctoken_table::new(ctx),
        emode_group,
    };

    let cap = ObligationOwnerCap {
        id: object::new(ctx),
        obligation_id: object::id(&obligation),
        market_type: type_name::with_defining_ids<MarketType>(),
        market_id: lending_market_id,
    };
    (obligation, cap)
}

public(package) fun accrue_interest<MarketType>(
    self: &mut Obligation<MarketType>,
    name: TypeName,
    asset_borrow_index: Decimal,
): &mut Debt {
    let debt = wit_table::borrow_mut(ObligationDebts {}, &mut self.debts, name);
    debt.accrue_interest(asset_borrow_index);
    debt
}

/// @title Module for hanlding withdraw base asset request from user
/// @notice User use sCoin to redeem the underlying asset
module protocol::withdraw;

use std::type_name::{Self, TypeName};
use sui::clock::Clock;
use sui::event::emit;
use sui::coin::Coin;

use x_oracle::x_oracle::XOracle;

use protocol::app::ProtocolApp;
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::ctoken::CToken;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_deposit_reward_type;

public struct WithdrawEvent has copy, drop {
    redeemer: address,

    market: TypeName,
    obligation: ID,

    withdraw_asset: TypeName,
    withdraw_amount: u64,
    ctokens_remaining: u64,

    burn_asset: TypeName,
    burn_amount: u64,
    time: u64,
}

public fun withdraw_as_coin<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    ctoken_to_burn: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = sui::clock::timestamp_ms(clock) / 1000;

    let (coin, ctokens_remaining) = market.handle_withdraw<MarketType, CoinType>(
        obligation_owner_cap.id(),
        ctoken_to_burn,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_deposit_reward_type(),
        obligation_owner_cap.id(),
        ctokens_remaining,
        clock
    );

    // emit Redeem Event
    emit(WithdrawEvent {
        redeemer: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        withdraw_asset: type_name::with_defining_ids<CoinType>(),
        withdraw_amount: coin.value(),
        ctokens_remaining,

        burn_asset: type_name::with_defining_ids<CToken<MarketType, CoinType>>(),
        burn_amount: ctoken_to_burn,

        time: now,
    });

    coin
}

#[allow(lint(self_transfer))]
public fun withdraw<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let coin = withdraw_as_coin<MarketType, CoinType>(
        app,
        market,
        obligation_owner_cap,
        coin_decimals_registry, 
        amount, 
        x_oracle, 
        clock, 
        ctx
    );
    transfer::public_transfer(coin, ctx.sender());
}

fun is_obligation_safe<MarketType>(
    emode_group: &EModeGroup,
    reserves: &GenericCoinTypeStorage<Reserve<MarketType>>,
    ema_spot_tolerance: &GenericCoinTypeStorage<Decimal>,

    obligation: &Obligation<MarketType>,

    coin_decimals_registry: &CoinDecimalsRegistry,
    x_oracle: &XOracle,
    clock: &Clock,
): bool {
    // make sure that their obligation still healthy, so users aren't borrowing over their collateral
    let borrow_weight_weighted_debt_value = debts_value_usd_non_liquidation(
        emode_group,
        reserves,
        ema_spot_tolerance,

        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    let (collateral_weighted_value, _) = collaterals_usd_non_liquidation(
        emode_group,
        reserves,
        ema_spot_tolerance,
        obligation,
        coin_decimals_registry,
        x_oracle,
        clock,
    );

    // NOTE: if collaterals_value == borrow_weight_weighted_debt_value, this is still safe, the boundary of safety
    collateral_weighted_value.ge(borrow_weight_weighted_debt_value)
}

