     1→module protocol::ctoken_table;
     2→
     3→use std::type_name::{Self, TypeName};
     4→use sui::bag::{Self, Bag};
     5→use sui::balance::{Self, Balance};
     6→
     7→use sui::table::{Self, Table};
     8→
     9→use protocol::ctoken::CToken;
    10→use protocol::error;
    11→use protocol::generic_store::{Self, GenericCoinTypeStorage};
    12→
    13→/// Tracks the ctoken stored and the underlying coin types
    14→public struct CTokenTable has key, store {
    15→    id: UID,
    16→    // a mapping from the underlying coin type to ctoken types
    17→    coin_types: GenericCoinTypeStorage<TypeName>,
    18→    // use table instead of vec set as one needs to query balance by TypeName while balances is a bag and borrow operations need explicit types
    19→    ctoken_values: Table<TypeName, u64>,
    20→    balances: Bag,
    21→}
    22→
    23→public(package) fun new(ctx: &mut TxContext): CTokenTable {
    24→    CTokenTable {
    25→        id: object::new(ctx),
    26→        coin_types: generic_store::new(ctx),
    27→        ctoken_values: table::new(ctx),
    28→        balances: bag::new(ctx),
    29→    }
    30→}
    31→
    32→public(package) fun ctoken_value_by_coin_type(self: &CTokenTable, name: TypeName): u64 {
    33→    if (!self.coin_types.supports_type<TypeName>(name)) { 0 } 
    34→    else {
    35→        let ctoken_type = self.coin_types.load_by_type(name);
    36→        self.ctoken_value_by_ctoken_type(*ctoken_type)
    37→    }
    38→}
    39→
    40→public(package) fun ctoken_value_by_ctoken_type(self: &CTokenTable, name: TypeName): u64 {
    41→    if (!self.ctoken_values.contains(name)) { return 0 };
    42→    *self.ctoken_values.borrow(name)
    43→}
    44→
    45→public(package) fun is_supporting_collateral<MarketType, CoinType>(self: &CTokenTable): bool {
    46→    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    47→    self.ctoken_values.contains(ctoken_type)
    48→}
    49→
    50→public(package) fun supported_coin_types(self: &CTokenTable): vector<TypeName> {
    51→    if (self.coin_types.is_empty()) { vector::empty() } 
    52→    else { self.coin_types.keys() }
    53→}
    54→
    55→public(package) fun support_collateral_token<MarketType, CoinType>(self: &mut CTokenTable) {
    56→    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    57→
    58→    // we are using ctoken type as the checking key and only coin_types to track actual collateral
    59→    assert!(!self.ctoken_values.contains(ctoken_type), error::constraint_double_support_ctoken());
    60→
    61→    self.coin_types.store<TypeName, CoinType>(ctoken_type);
    62→
    63→    self.balances.add(ctoken_type, balance::zero<CToken<MarketType, CoinType>>());
    64→    self.ctoken_values.add(ctoken_type, 0);
    65→}
    66→
    67→public(package) fun join_ctoken<MarketType, CoinType>(self: &mut CTokenTable, balance: Balance<CToken<MarketType, CoinType>>) {
    68→    assert!(balance.value() > 0, error::reserve_join_zero_value());
    69→    assert!(self.coin_types.supports<TypeName, CoinType>());
    70→
    71→    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    72→    
    73→    let in_bag_balance = bag::borrow_mut<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
    74→    let total = in_bag_balance.join(balance);
    75→
    76→    let val = self.ctoken_values.borrow_mut(ctoken_type);
    77→    *val = total;
    78→}
    79→
    80→/// Reverts if amount is more than balance, caller should ensure the condition is met.
    81→public(package) fun split_ctoken<MarketType, CoinType>(self: &mut CTokenTable, amount: u64): Balance<CToken<MarketType, CoinType>> {
    82→    assert!(amount > 0, error::reserve_split_zero_value());
    83→
    84→    let ctoken_type = ctoken_type_name<MarketType, CoinType>();
    85→    let in_bag_balance = bag::borrow_mut<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
    86→
    87→    assert!(in_bag_balance.value() >= amount, error::constraint_split_ctoken_too_many());
    88→
    89→    let b = in_bag_balance.split(amount);
    90→    if (in_bag_balance.value() == 0) {
    91→        self.coin_types.remove<TypeName, CoinType>();
    92→
    93→        let empty_balance = bag::remove<TypeName, Balance<CToken<MarketType, CoinType>>>(&mut self.balances, ctoken_type);
    94→        empty_balance.destroy_zero();
    95→        
    96→        self.ctoken_values.remove(ctoken_type);
